package hashline

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strings"
)

// Auto-generated file detection matching crates/edit/src/path_policy.rs:234,554-675.
// upstream: crates/edit/src/path_policy.rs

var (
	generatedFilenamePatterns = []*regexp.Regexp{
		regexp.MustCompile(`^zz_generated\.`),
		regexp.MustCompile(`\.pb\.(go|cc|h|c)$`),
		regexp.MustCompile(`_pb2\.py$`),
		regexp.MustCompile(`_pb2_grpc\.py$`),
		regexp.MustCompile(`\.gen\.(go|ts|js|py)$`),
		regexp.MustCompile(`\.swagger\.json$`),
	}
	generatedContentPatterns = []*regexp.Regexp{
		regexp.MustCompile(`(?i)@generated\b`),
		regexp.MustCompile(`(?i)\bcode\s+generated\s+by\s+[a-z0-9_.-]+`),
		regexp.MustCompile(`(?i)\bcode\s+generated\b.*\bdo\s+not\s+edit\b`),
		regexp.MustCompile(`(?i)\bthis\s+file\s+was\s+automatically\s+generated\b`),
		regexp.MustCompile(`(?i)\bgenerated\s+by\s+(?:protoc(?:-gen-[\w-]+)?|sqlc|buf|swagger(?:-codegen)?|openapi(?:-generator)?|grpc-gateway|mockery|stringer|easyjson|deepcopy-gen|defaulter-gen|conversion-gen|client-gen|lister-gen|informer-gen|kysely-codegen|napi-rs)\b`),
	}
)

// AutoGeneratedMessage returns the model-facing generated-file rejection when applicable,
// or empty string when the file is editable.
// upstream: crates/edit/src/path_policy.rs:234
func AutoGeneratedMessage(display string, head []byte) string {
	marker := generatedFilename(display)
	if marker == "" {
		limit := min(len(head), 1024)
		marker = detectGeneratedMarker(string(head[:limit]), display)
	}
	if marker == "" {
		return ""
	}
	return fmt.Sprintf(
		"Cannot modify auto-generated file: %s\n\nThis file appears to be automatically generated (detected marker: \"%s\").\nAuto-generated files should not be edited directly. Instead:\n1. Find the source file or generator configuration\n2. Make changes to the source\n3. Regenerate the file",
		display, marker,
	)
}

func generatedFilename(display string) string {
	slash := strings.ReplaceAll(display, "\\", "/")
	name := slash
	if idx := strings.LastIndexByte(slash, '/'); idx >= 0 {
		name = slash[idx+1:]
	}
	for _, re := range generatedFilenamePatterns {
		if re.MatchString(name) {
			return name
		}
	}
	return ""
}

func detectGeneratedMarker(content, display string) string {
	styles := commentStylesForPath(display)
	if len(styles) == 0 {
		return ""
	}
	header := leadingCommentText(strings.TrimPrefix(content, BOM), styles)
	for _, re := range generatedContentPatterns {
		if m := re.FindString(header); m != "" {
			return m
		}
	}
	return ""
}

func commentStylesForPath(display string) []string {
	slash := strings.ReplaceAll(display, "\\", "/")
	name := strings.ToLower(slash)
	if idx := strings.LastIndexByte(name, '/'); idx >= 0 {
		name = name[idx+1:]
	}
	switch name {
	case "dockerfile", "makefile", "justfile":
		return []string{"hash"}
	}
	ext := strings.TrimPrefix(filepath.Ext(name), ".")
	switch ext {
	case "c", "cc", "cpp", "cs", "dart", "go", "h", "hpp", "java", "js", "jsx", "kt", "kts", "mjs", "cjs", "php", "rs", "scala", "swift", "ts", "tsx":
		return []string{"slash"}
	case "py", "rb", "sh", "bash", "zsh", "yml", "yaml", "toml", "ini", "cfg", "conf", "env", "pl", "r":
		return []string{"hash"}
	case "sql":
		return []string{"sql"}
	case "html", "htm", "xml", "svg", "xhtml":
		return []string{"html"}
	default:
		return nil
	}
}

func leadingCommentText(content string, styles []string) string {
	hasStyle := func(target string) bool {
		for _, s := range styles {
			if s == target {
				return true
			}
		}
		return false
	}
	slashStyle := hasStyle("slash")
	hashStyle := hasStyle("hash")
	sqlStyle := hasStyle("sql")
	htmlStyle := hasStyle("html")

	var result []string
	started := false
	slashBlock := false
	htmlBlock := false
	lines := strings.Split(content, "\n")
	limit := min(len(lines), 40)
	for idx := range limit {
		line := strings.TrimSpace(strings.TrimSuffix(lines[idx], "\r"))
		if idx == 0 && strings.HasPrefix(line, "#!") {
			continue
		}
		if slashBlock {
			result = append(result, line)
			slashBlock = !strings.Contains(line, "*/")
			continue
		}
		if htmlBlock {
			result = append(result, line)
			htmlBlock = !strings.Contains(line, "-->")
			continue
		}
		if line == "" {
			if started {
				result = append(result, "")
			}
			continue
		}
		accepted := (slashStyle && strings.HasPrefix(line, "//")) ||
			(hashStyle && strings.HasPrefix(line, "#")) ||
			(sqlStyle && strings.HasPrefix(line, "--")) ||
			(htmlStyle && strings.HasPrefix(line, "<!--"))
		if !accepted && !(slashStyle && strings.HasPrefix(line, "/*")) {
			break
		}
		started = true
		result = append(result, line)
		if slashStyle && strings.HasPrefix(line, "/*") {
			slashBlock = !strings.Contains(line, "*/")
		}
		if htmlStyle && strings.HasPrefix(line, "<!--") {
			htmlBlock = !strings.Contains(line, "-->")
		}
	}
	return strings.Join(result, "\n")
}
